<script setup lang="ts">
import { ref, computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { useSettingsStore } from '../stores/settings'
import { useToastStore } from '../stores/toast'
import { errorText } from '../utils/api'
const { t } = useI18n(); const settings = useSettingsStore(); const toast = useToastStore(); const error = ref('')
const themes = computed(() => ['system','light','dark'].map(value => ({ label: t('settings.' + value), value })))
const closes = computed(() => ['ask','tray','exit'].map(value => ({ label: t('settings.' + value), value })))
async function save() { error.value = ''; const keys = Object.values(settings.values.shortcuts).map(x => x.toLowerCase()); if (new Set(keys).size !== keys.length || keys.some(k => !/^(ctrl|alt|shift|meta)\+.+/.test(k))) { error.value = t('settings.invalidShortcut'); return }; try { await settings.save(); toast.show(t('common.saved')) } catch (e) { error.value = errorText(e) } }
</script>
<template><section class="page"><div class="page-head"><div><h1>{{ t('settings.title') }}</h1><p class="muted">{{ t('settings.description') }}</p></div><n-button type="primary" @click="save">{{ t('common.save') }}</n-button></div><p v-if="error" class="error-detail" role="alert">{{ error }}</p><div class="panel"><h2>{{ t('settings.appearance') }}</h2><div class="setting-row"><span>{{ t('settings.theme') }}</span><n-select v-model:value="settings.values.theme" :options="themes"/></div><div class="setting-row"><span>{{ t('settings.language') }}</span><n-select v-model:value="settings.values.language" :options="[{label:'简体中文',value:'zh-CN'},{label:'English',value:'en'}]"/></div><div class="setting-row"><span>{{ t('settings.closeAction') }}</span><n-select v-model:value="settings.values.closeAction" :options="closes"/></div><div class="setting-row"><span>{{ t('settings.scrollback') }}</span><n-input-number v-model:value="settings.values.scrollback" :min="1000" :max="100000" :step="1000"/></div><div class="setting-row"><span>{{ t('settings.fontSize') }}</span><n-input-number v-model:value="settings.values.fontSize" :min="10" :max="32"/></div></div><div class="panel" style="margin-top:20px"><h2>{{ t('settings.notifications') }}</h2><div v-for="key in (['disconnected','completed','approval'] as const)" :key="key" class="setting-row"><span>{{ t('settings.' + key) }}</span><n-switch v-model:value="settings.values.notifications[key]"/></div></div><div class="panel" style="margin-top:20px"><h2>{{ t('settings.shortcuts') }}</h2><p class="muted">{{ t('settings.shortcutsHelp') }}</p><div v-for="key in (['newTerminal','saveFile','focusDock','closeTab','nextTab','previousTab','split'] as const)" :key="key" class="setting-row"><span>{{ t('settings.' + key) }}</span><n-input v-model:value="settings.values.shortcuts[key]"/></div></div></section></template>
